-- Audit record of the import (only when this run inserted something; a no-op re-run leaves no audit row)
IF @inserted > 0
    INSERT INTO qa.AuditLog (UserId, Action, EntityType, EntityId, OldValue, NewValue)
    VALUES (NULL, N'EXCEL_IMPORT', N'RejectionPhenomena', NULL, NULL, N'{"GDC_SHOP": {"raw": 25, "imported": 25, "skipped": 0}, "CNC_SHOP": {"raw": 53, "imported": 52, "skipped": 1}, "PRE_TREATMENT": {"raw": 34, "imported": 34, "skipped": 0}, "FINAL": {"raw": 34, "imported": 34, "skipped": 0}}');

-- Post-condition check: abort and roll back unless every seeded code is present
DECLARE @cnt int;
SELECT @cnt = COUNT(*) FROM qa.RejectionPhenomena p JOIN qa.InspectionStages s ON s.Id = p.InspectionStageId WHERE s.StageCode = N'GDC_SHOP' AND p.PhenomenonCode LIKE N'GDC_SHOP-[0-9][0-9][0-9]' AND TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) <= 25;
IF @cnt <> 25 THROW 50001, N'Seed check failed for GDC_SHOP: expected all 25 seeded codes GDC_SHOP-001..025', 1;
SELECT @cnt = COUNT(*) FROM qa.RejectionPhenomena p JOIN qa.InspectionStages s ON s.Id = p.InspectionStageId WHERE s.StageCode = N'CNC_SHOP' AND p.PhenomenonCode LIKE N'CNC_SHOP-[0-9][0-9][0-9]' AND TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) <= 52;
IF @cnt <> 52 THROW 50001, N'Seed check failed for CNC_SHOP: expected all 52 seeded codes CNC_SHOP-001..052', 1;
SELECT @cnt = COUNT(*) FROM qa.RejectionPhenomena p JOIN qa.InspectionStages s ON s.Id = p.InspectionStageId WHERE s.StageCode = N'PRE_TREATMENT' AND p.PhenomenonCode LIKE N'PRE_TREATMENT-[0-9][0-9][0-9]' AND TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) <= 34;
IF @cnt <> 34 THROW 50001, N'Seed check failed for PRE_TREATMENT: expected all 34 seeded codes PRE_TREATMENT-001..034', 1;
SELECT @cnt = COUNT(*) FROM qa.RejectionPhenomena p JOIN qa.InspectionStages s ON s.Id = p.InspectionStageId WHERE s.StageCode = N'FINAL' AND p.PhenomenonCode LIKE N'FINAL-[0-9][0-9][0-9]' AND TRY_CAST(RIGHT(p.PhenomenonCode, 3) AS int) <= 34;
IF @cnt <> 34 THROW 50001, N'Seed check failed for FINAL: expected all 34 seeded codes FINAL-001..034', 1;
COMMIT TRANSACTION;
PRINT N'Phenomena seed complete.';
